import { existsSync, statSync } from "node:fs";
import { DISPATCH_INPUTS, ID_TOKEN_PERMISSION, OLD_CONFIG, PREFIX, SECRET_REFERENCE, WORKFLOW, WORKFLOW_DIRECTORY, WORKFLOW_NAMES, } from "./constants.js";
import { splitLines, ValueError, within } from "./runtime.js";
function isFile(file) {
    try {
        return statSync(file).isFile();
    }
    catch {
        return false;
    }
}
export function findWorkflow(root) {
    for (const name of WORKFLOW_NAMES) {
        if (isFile(within(root, `${WORKFLOW_DIRECTORY}/${name}`))) {
            return name;
        }
    }
    return null;
}
export function refuseOldSetup(root) {
    if (existsSync(within(root, OLD_CONFIG))) {
        throw new ValueError(`This cloud replay setup was made by an older SDK. Delete ${OLD_CONFIG} and ${WORKFLOW_DIRECTORY}/${WORKFLOW}, then run bitfab-replay --cloud-init`);
    }
}
export function setupWorkflow(root) {
    refuseOldSetup(root);
    const name = findWorkflow(root);
    if (name === null) {
        throw new ValueError(`No ${WORKFLOW_DIRECTORY}/${WORKFLOW} yet. Run bitfab-replay --cloud-init, or ask your coding agent for bitfab:setup cloud`);
    }
    return name;
}
export function workflowSecrets(text) {
    const secrets = {};
    for (const match of text.matchAll(SECRET_REFERENCE)) {
        secrets[match[1]] = match[2] || match[3];
    }
    return secrets;
}
export function secretsPage(repo, environment) {
    if (environment) {
        return `https://github.com/${repo}/settings/environments`;
    }
    return `https://github.com/${repo}/settings/secrets/actions`;
}
export function runningWorkflow(root) {
    const reference = process.env.GITHUB_WORKFLOW_REF ?? "";
    const match = /(\.github\/workflows\/[^@]+)@/.exec(reference);
    if (match) {
        return within(root, match[1]);
    }
    return within(root, `${WORKFLOW_DIRECTORY}/${findWorkflow(root) ?? WORKFLOW}`);
}
function escapeRegExp(text) {
    return text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}
export function declaredInputs(text) {
    return new Set(DISPATCH_INPUTS.filter((name) => new RegExp(`^[ \\t]*"?${escapeRegExp(name)}"?[ \\t]*:`, "m").test(text)));
}
export function grantsIdToken(text) {
    return ID_TOKEN_PERMISSION.test(text);
}
export function indentation(line) {
    return line.length - line.replace(/^[ \t]+/, "").length;
}
export function blockEnd(lines, start, indent) {
    let end = start + 1;
    while (end < lines.length &&
        (!lines[end].trim() ||
            lines[end].trimStart().startsWith("#") ||
            indentation(lines[end]) > indent)) {
        end += 1;
    }
    while (end > start + 1 &&
        (!lines[end - 1].trim() ||
            (lines[end - 1].trimStart().startsWith("#") &&
                indentation(lines[end - 1]) <= indent))) {
        end -= 1;
    }
    return end;
}
export function holdsYaml(line) {
    return Boolean(line.trim()) && !line.trimStart().startsWith("#");
}
export function childIndent(lines, index, end, fallback) {
    for (let row = index + 1; row < end; row += 1) {
        if (holdsYaml(lines[row])) {
            return lines[row].slice(0, indentation(lines[row]));
        }
    }
    return fallback;
}
export function indentPattern(step) {
    return escapeRegExp(step);
}
export function pushTrigger(lines) {
    for (const [index, line] of lines.entries()) {
        if (/^"?on"?[ \t]*:[ \t]*(#.*)?$/.test(line)) {
            const end = blockEnd(lines, index, 0);
            const step = childIndent(lines, index, end, "  ");
            const pattern = new RegExp(`^${indentPattern(step)}"?push"?[ \\t]*:.*$`);
            let row = null;
            for (let at = index + 1; at < end; at += 1) {
                if (pattern.test(lines[at])) {
                    row = at;
                    break;
                }
            }
            if (row === null) {
                return null;
            }
            return lines.slice(row, blockEnd(lines, row, step.length));
        }
        if (/^"?on"?[ \t]*:/.test(line)) {
            return /\bpush\b/.test(line) ? [line] : null;
        }
    }
    return null;
}
export function startsOnPush(text) {
    const trigger = pushTrigger(splitLines(text)) ?? [];
    return (trigger.some((line) => line.includes(PREFIX)) &&
        !trigger.some((line) => line.includes("branches-ignore")));
}
